<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><?php if($readOnly):?><p><a class="button" href="<?= site_url('admin/students/'.$student['id'].'/edit') ?>">Edit student</a></p><?php endif ?><form method="post" action="<?= $readOnly?'#':site_url(isset($student['id'])?'admin/students/'.$student['id'].'/edit':'admin/students') ?>"><?php if(!$readOnly):?><?= csrf_field() ?><?php endif ?><?php foreach(['student_id'=>'Student ID','full_name'=>'Full name','institutional_email'=>'Institutional email','program'=>'Program','program_code'=>'Program code','specialization'=>'Specialization','department'=>'Department'] as $key=>$label):?><label><?= $label ?><input <?= $readOnly?'readonly':'' ?> name="<?= $key ?>" maxlength="<?= $key==='student_id'||$key==='program_code'?30:150 ?>" value="<?= esc($student[$key]??'','attr') ?>" <?= in_array($key,['student_id','full_name','institutional_email','program','department'],true)?'required':'' ?>></label><?php endforeach ?><label>Enrollment status<select <?= $readOnly?'disabled':'' ?> name="enrollment_status"><option value="enrolled" <?= ($student['enrollment_status']??'')==='enrolled'?'selected':'' ?>>Enrolled</option><option value="not_enrolled" <?= ($student['enrollment_status']??'')==='not_enrolled'?'selected':'' ?>>Not enrolled</option></select></label><?php if(!$readOnly):?><button>Save student</button><?php endif ?></form><p><a href="<?= site_url('admin/students') ?>">Back to students</a></p><?= $this->endSection() ?>
